function EXTRA(R,ICON){
 /* hook: the ringing capacitor voltage of the series RLC (computed) and its two poles */
 ICON.ctRing=(x,y)=>`<g transform="translate(${x-210} ${y-105})">${CT_box(0,0,420,210,{st:BLU,sw:3,r:18})}${CT_T(20,36,CT_vC+' after the switch',{fs:24,fw:800,fill:BLU})}${CT_L(30,180,400,180,CT_AX,2)}${CT_L(30,180-10*10,400,180-10*10,CT_AX,2,'stroke-dasharray="6 6"')}${CT_T(400,72,'10 V',{fs:22,fw:700,a:'end',fill:CT_MUT})}${CT_curve(CT_vCring,0,3,30,400,180,10,BLU,5)}</g>`;
 ICON.ctPoles=(x,y)=>`<g transform="translate(${x-210} ${y-105})">${CT_box(0,0,420,210,{st:ORG,sw:3,r:18})}${CT_T(20,36,'its poles',{fs:24,fw:800,fill:ORG})}${CT_arrow(30,120,240,120,CT_AX,2)}${CT_arrow(190,204,190,30,CT_AX,2)}${CT_x(154,48,ORG)}${CT_x(154,192,ORG)}${CT_T(256,108,'decay: 2 s⁻¹',{fs:24,fw:800,fill:ORG})}${CT_T(256,148,'ring: 4 rad/s',{fs:24,fw:800,fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctRecS=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="330" rx="18" fill="#EDF2FF"/>${CT_cap(20,150,90,CT_INK,4)}${CT_T(85,150,'holds 4 V',{fs:26,fw:800,a:'middle',fill:CT_MUT})}${CT_arrow(180,90,240,90,CT_INK,4)}${CT_T(320,100,'in s',{fs:30,fw:800,a:'middle',fill:BLU})}${CT_L(10,250,60,250,CT_INK,4)}${CT_Z(60,250,250,'10/s',BLU)}${CT_vs(300,250,34,ORG)}${CT_L(334,250,410,250,CT_INK,4)}${CT_T(300,318,'4/s',{fs:32,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.ctRecPZ=(x,y)=>{let p=[];for(let i=0;i<=120;i++){const w=20*i/120;p.push([220+w*9.5,300-Math.min(5.2,CT_H(2,w))*44])}let q=[];for(let i=0;i<=120;i++){const w=20*i/120;q.push([220+w*9.5,300-CT_H(10,w)*44])}
  return `<g transform="translate(${x-210} ${y-165})">${CT_arrow(10,175,190,175,CT_AX,2)}${CT_arrow(160,320,160,30,CT_AX,2)}${CT_x(150,60,BLU)}${CT_x(150,290,BLU)}${CT_x(110,85,ORG)}${CT_x(110,265,ORG)}${CT_L(220,300,420,300,CT_AX,2)}${CT_poly(p,BLU,4)}${CT_poly(q,ORG,4)}${CT_T(330,60,'5.03',{fs:26,fw:800,fill:BLU})}${CT_T(372,248,'1.15',{fs:26,fw:800,fill:ORG})}</g>`};
 ICON.ctRecAB=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="330" rx="18" fill="#EBFBEE"/>${CT_T(20,90,'A =',{fs:34,fw:800,fill:GRN})}${CT_poly([[104,44],[94,44],[94,140],[104,140]],GRN,4)}${CT_poly([[246,44],[256,44],[256,140],[246,140]],GRN,4)}${CT_T(140,80,'−4',{fs:32,fw:800,a:'middle',fill:GRN})}${CT_T(212,80,'−2',{fs:32,fw:800,a:'middle',fill:GRN})}${CT_T(140,126,'10',{fs:32,fw:800,a:'middle',fill:GRN})}${CT_T(212,126,'0',{fs:32,fw:800,a:'middle',fill:GRN})}${CT_T(280,104,'→ −2 ± j4',{fs:28,fw:800,fill:CT_INK})}${CT_L(20,280,410,280,CT_AX,2)}${CT_curve(t=>CT_vCring(t)-10,0,3,20,410,250,7,GRN,5)}${CT_T(410,326,'rings while it decays',{fs:22,fw:700,a:'end',fill:CT_MUT})}</g>`;
}
